// Vendored from the auth-emails service,
// `npm-packages-private/auth-emails/authEmailsApi.ts` in the
// get-convex/convex repository, which is the source of truth. Copy
// changes from there; do not edit this file by hand.

/**
 * The public API of the auth-emails service, for typesafe calls from outside this project.
 *
 * Convex Auth vendors this file (in
 * `packages/core/src/components/email/authEmailsApi.ts`) and calls the service with
 * `ConvexHttpClient`, so the file imports only from `convex/server` and
 * `convex/values`. `convex/authEmailsApi.test.ts` checks that the references
 * below match the functions that the service deploys.
 *
 * Change the API compatibly: deployed versions of Convex Auth keep sending
 * the old arguments.
 *
 * @module
 */
import { makeFunctionReference } from "convex/server";
import { Infer, ObjectType, v } from "convex/values";

/**
 * The emails the service can send. It owns the copy of each template; the
 * caller only gives the values that go into it.
 */
export const vTemplate = v.union(
  v.object({
    kind: v.literal("validateEmail"),
    /** The `https:` link that validates the address. */
    link: v.string(),
    /** How long the link stays valid, in milliseconds. */
    ttlMs: v.number(),
  }),
  v.object({
    kind: v.literal("resetPassword"),
    /** The `https:` link that opens the password reset page. */
    link: v.string(),
    /** How long the link stays valid, in milliseconds. */
    ttlMs: v.number(),
  }),
  v.object({ kind: v.literal("passwordChanged") }),
  v.object({
    kind: v.literal("emailChanged"),
    /** The address that replaced the recipient's address on the account. */
    newEmail: v.string(),
  }),
);
export type Template = Infer<typeof vTemplate>;

export const sendArgs = {
  /** The recipient address. */
  to: v.string(),
  /** The name of the app that sends the email, shown in the copy. */
  appName: v.optional(v.string()),
  template: vTemplate,
};
export type SendArgs = ObjectType<typeof sendArgs>;

/**
 * The result of `emails:send`. `rateLimited` is a result rather than an
 * error, so that the caller can log it and retry after `retryAfterMs`.
 */
export const vSendResult = v.union(
  v.object({ status: v.literal("sent") }),
  v.object({ status: v.literal("rateLimited"), retryAfterMs: v.number() }),
);
export type SendResult = Infer<typeof vSendResult>;

export const authEmailsApi = {
  emails: {
    /**
     * Send one email. The caller authenticates with its deployment's
     * `getServiceToken("ai-gateway")` token, through
     * `ConvexHttpClient.setAuth`.
     */
    send: makeFunctionReference<"mutation", SendArgs, SendResult>(
      "emails:send",
    ),
  },
};
